  "Torrent engine offline.": "Торрент-движок не в сети.",
  "Torrent engine said {status}.": "Торрент-движок вернул {status}.",
  "Torrent engine said {status}: {reason}": "Торрент-движок вернул {status}: {reason}",
  "Torrents": "Торренты",
